/* AUD003-B15.2A: isolated real-core Ren/Nada ablation. No production imports or save writes.
 * Run from repository root: node docs/research/aud003-b15-2a-read-move.js [count]
 * B14.6 is the same-pressure reference, NOT live production. Art/Sava/Liora remain B14.6.
 */
"use strict";
const VARIANTS=["b14","b15","b15-no-share","b15-nada3","b15-ren12"];
const REFINEMENTS=["b15-nada-adaptive","b15-nada-cd1"];
const TIERS={
 early:{skill:1,level:2,stars:1,rush:.90,mixed:.72},
 trained:{skill:6,level:12,stars:1,rush:1.12,mixed:.90}
};
const SQUADS=[
 ["ren","art"],["ren","art","nada"],["ren","liora","nada"],
 ["art","nada","sava"],["liora","nada","sava"],["ren","art","sava"],
 ["b14-striker","art","nada"],["b14-striker","art","sava"],
 ["b14-striker","b14-medic","b14-breaker"]
];
function replaceOnce(s,a,b){if(s.split(a).length!==2)throw Error("B15.2A anchor: "+a);return s.replace(a,b);}
function kit(actor,id,base,v){
 if(!base||!["ren","nada"].includes(actor?.id))return base;
 const level=actor.skillLevels?.[id]??1;
 if(!Number.isInteger(level)||level<1||level>6)throw Error("skill level");
 const i=level-1, ren=actor.id==="ren";
 const damage=ren?{basic:[1,1.05,1.1,1.1,1.18,1.25],special:[1.05,1.1,1.15,1.2,1.25,1.3],powerful:[1.55,1.6,1.65,1.7,1.78,1.85]}:
 {basic:[.8,.85,.9,.95,1,1.05],special:[.7,.74,.78,.82,.86,.9],powerful:[.5,.54,.58,.62,.66,.7]};
 if(id==="passive"){
  const rules={...base.combatRules};
  if(ren){rules.readMoveBonusPercentPerStack=v==="b15-ren12"?12:[8,8,9,9,10,10][i];rules.gardensEvasionBonus=[5,5,6,6,7,8][i];}
  else rules.gardensAccuracyBonus=[5,5,6,6,7,8][i];
  return {...base,combatRules:rules};
 }
 if(!damage[id])return base;
 const a={...base,multiplier:damage[id][i],cooldown:{basic:0,special:2,powerful:3}[id]};
 if(ren){
  if(id==="basic"){if(level>=4)a.onHitStatus={type:"slowed",amount:20,turns:level===6?2:1};else delete a.onHitStatus;}
  if(id==="special")a.weakening=2;
  if(id==="powerful")delete a.followUpStatusAll;
 }else{
  a.onHitStatus={type:"read-move",stacks:id==="basic"?1:2,turns:2};
  // Deliberately low-damage three-stack alternative, not a non-damaging skill:
  // native hit/resist contract still applies. An exact non-damaging variant is future work.
  if(v==="b15-nada3"&&id==="special"){a.multiplier=[.25,.27,.29,.31,.33,.35][i];a.cooldown=3;a.onHitStatus.stacks=3;}
  if(id==="special"&&level>=5){if(v==="b15-nada-adaptive")a.onHitStatus.stacks=3;if(v==="b15-nada-cd1")a.cooldown=1;}
 }
 return a;
}
function setup(source,labSource,variant,tier){
 if(![...VARIANTS,...REFINEMENTS].includes(variant)||!TIERS[tier])throw Error("invalid configuration");
 const t=TIERS[tier];
 let s=source,l=labSource;
 l=replaceOnce(l,"skillLevels:{basic:1,special:1,powerful:1,passive:1}","skillLevels:"+JSON.stringify({basic:t.skill,special:t.skill,powerful:t.skill,passive:t.skill}));
 l=replaceOnce(l,"{level:2,stars:1}","{level:"+t.level+",stars:"+t.stars+"}");
 l=replaceOnce(l,'const scale=scenario==="rush"?.90:.72;', 'const scale=scenario==="rush"?'+t.rush+':'+t.mixed+';');
 if(variant!=="b14"){
  s=replaceOnce(s,'return typeof SkillCore!=="undefined"?SkillCore.apply(ability,actor,abilityId):ability;',
    'return ('+kit.toString()+')(actor,abilityId,typeof SkillCore!=="undefined"?SkillCore.apply(ability,actor,abilityId):ability,'+JSON.stringify(variant)+');');
  l=replaceOnce(l,"shared:12","shared:"+(variant==="b15-no-share"?0:10));
  // Shared bonus only on the real primary action. The existing B14.6 assist
  // emits separate damage but is not a root ability. Do not award it this bonus.
  l=replaceOnce(l,'actor.side==="ally"&&actor.id!=="ren"&&actor.id!=="nada"&&CombatStatusCore.read(target,"read-move")?.stacks>0',
    'actor.side==="ally"&&actor.id!=="ren"&&actor.id!=="nada"&&battle.events.some(e=>e.type==="ability"&&e.actorId===actor.id&&e.targetId===target.id)&&CombatStatusCore.read(target,"read-move")?.stacks>0');
 }
 const lab=new Function("module",l+"\nreturn B146;")({exports:{}});
 return {lab,api:lab.make(s,"visible")};
}
const sum=(xs,f)=>xs.reduce((n,x)=>n+f(x),0);
function run(ctx,squad,scenario,seed,policy="tactical"){
 const {lab,api}=ctx,b=lab.start(api,squad,scenario,seed);
 const allies=()=>b.fighters.filter(f=>f.side==="ally"),max=sum(allies(),f=>f.maxHp+f.maxProtection);
 let actions=0,marks=0,predicted=0,nadaSpecial=0,nadaSpecialPredicted=0,renDamage=0,otherDamage=0;
 const trace=[];
 while(b.active&&actions<160){
  const actor=b.fighters[b.currentActor];
  const target=b.fighters.flatMap((f,i)=>f.side==="enemy"&&f.hp>0?[i]:[]).sort((i,j)=>b.fighters[i].hp+b.fighters[i].protection-b.fighters[j].hp-b.fighters[j].protection||i-j)[0];
  const p=policy==="basic"?{abilityId:"basic",targetIndex:target,enemy:target}:lab.plan(api,b,true);
  if(!p||!lab.step(api,b,p.abilityId,p.targetIndex,p.enemy))throw Error("illegal "+JSON.stringify({squad,scenario,seed,policy,actor:actor?.id,p}));
  actions++;
  if(actor.id==="nada"&&p.abilityId==="special")nadaSpecial++;
  for(const e of b.events){
   if(e.type==="effect"&&e.effect==="read-move")marks++;
   if(e.type==="read-move-predicted"){predicted++;if(actor.id==="nada"&&p.abilityId==="special")nadaSpecialPredicted++;}
   if(e.type==="damage"&&e.actorId==="ren")renDamage+=e.amount;
   if(e.type==="damage"&&e.actorId&&e.actorId!=="ren"&&allies().some(f=>f.id===e.actorId))otherDamage+=e.amount;
  }
  trace.push([actor.id,p.abilityId,p.targetIndex,b.fighters.map(f=>[f.id,f.hp,f.protection,f.meter,api.T.read(f,"read-move")?.stacks??0])]);
 }
 if(b.active)throw Error("turn limit "+JSON.stringify({squad,scenario,seed,policy}));
 lab.validate(b);
 return {win:b.winner==="ally",quality:b.winner==="ally"&&allies().every(f=>f.hp>0),pool:sum(allies(),f=>f.hp+f.protection)/max,actions,marks,predicted,nadaSpecial,nadaSpecialPredicted,renDamage,otherDamage,trace};
}
function summarize(rows){const out={n:rows.length,w:sum(rows,r=>+r.win),q:sum(rows,r=>+r.quality)};
 for(const k of ["pool","actions","marks","predicted","nadaSpecial","nadaSpecialPredicted","renDamage","otherDamage"])out[k]=+(sum(rows,r=>r[k])/rows.length).toFixed(3);
 return out;}
function contracts(source,labSource){
 const checks=[];
 const check=(label,p)=>{if(!p)throw Error(label);checks.push(label);};
 const c=setup(source,labSource,"b15","early"),d=c.api.D,t=c.api.T;
 const hero=(id,level)=>({id,side:"ally",skillLevels:{basic:level,special:level,powerful:level,passive:level}});
 check("Ren slow begins L4",!d.get(hero("ren",3),"basic").onHitStatus&&d.get(hero("ren",4),"basic").onHitStatus.amount===20);
 check("Ren L6 synergy max 40%",d.get(hero("ren",6),"passive").combatRules.readMoveBonusPercentPerStack*4===40);
 check("Nada two stacks CD2",d.get(hero("nada",6),"special").onHitStatus.stacks===2&&d.get(hero("nada",6),"special").cooldown===2);
 const a=setup(source,labSource,"b15-nada3","early");
 check("alternative three stacks CD3",a.api.D.get(hero("nada",1),"special").onHitStatus.stacks===3&&a.api.D.get(hero("nada",1),"special").cooldown===3);
 check("owner leader rule",d.get(hero("art",1),"leader")===null&&d.get(hero("sava",1),"leader")===null);
 const b=c.lab.start(c.api,["ren","art","nada"],"rush",701);
 const enemy=b.fighters.find(f=>f.side==="enemy");
 check("stack cap",t.applyReadMove(enemy,3,2)&&t.applyReadMove(enemy,2,2)&&t.read(enemy,"read-move").stacks===4);
 check("spend three retains one",t.spendReadMove(enemy,3)&&t.read(enemy,"read-move").stacks===1);
 check("expiry after two own turns",t.tickOwnTurn(enemy)&&t.read(enemy,"read-move").remaining===1&&t.tickOwnTurn(enemy)&&t.read(enemy,"read-move")===null);
 const x=run(c,["ren","art","nada"],"rush",701),y=run(c,["ren","art","nada"],"rush",701);
 check("same seed identical command/state trace",JSON.stringify(x)===JSON.stringify(y));
 // Source drift fails closed: validate that the patch is not silently skipped.
 let failed=false;try{setup(source.replace('return typeof SkillCore!=="undefined"?SkillCore.apply(ability,actor,abilityId):ability;','return ability;'),labSource,"b15","early");}catch{failed=true;}
 check("missing anchor rejects candidate",failed);
 return checks;
}
function experiment(source,labSource,count=20){
 if(!Number.isInteger(count)||count<1||count>60)throw Error("count");
 const seeds=Array.from({length:count},(_,i)=>Math.imul(i+17131,0x9e3779b1)>>>0);
 const checks=contracts(source,labSource),cells=[];
 for(const tier of Object.keys(TIERS))for(const variant of VARIANTS){
  const ctx=setup(source,labSource,variant,tier);
  for(const squad of SQUADS)for(const scenario of ["rush","mixed"]){
   const runs=seeds.map(seed=>run(ctx,squad,scenario,seed));
   cells.push({tier,variant,squad:squad.join("+"),scenario,policy:"tactical",...summarize(runs)});
   if(variant==="b15"){
    const basics=seeds.map(seed=>run(ctx,squad,scenario,seed,"basic"));
    cells.push({tier,variant,squad:squad.join("+"),scenario,policy:"basic",...summarize(basics)});
   }
  }
 }
 return {checks,seedCount:count,seeds,tiers:TIERS,battles:sum(cells,c=>c.n),cells};
}
function refine(source,labSource,count=20){
 if(!Number.isInteger(count)||count<1||count>60)throw Error("count");
 const seeds=Array.from({length:count},(_,i)=>Math.imul(i+28133,0x9e3779b1)>>>0);
 const checks=contracts(source,labSource),cells=[];
 for(const tier of Object.keys(TIERS))for(const variant of tier==="early"?["b14","b15"]:["b14","b15","b15-nada3",...REFINEMENTS]){
  const ctx=setup(source,labSource,variant,tier);
  for(const squad of SQUADS.filter(s=>s.includes("nada")||s.length===2))for(const scenario of ["rush","mixed"]){
   cells.push({tier,variant,squad:squad.join("+"),scenario,policy:"tactical",...summarize(seeds.map(seed=>run(ctx,squad,scenario,seed)))});
  }
 }
 const a=setup(source,labSource,"b15-nada-adaptive","trained"),b=setup(source,labSource,"b15-nada-cd1","trained");
 const f={id:"nada",side:"ally",skillLevels:{special:6}};
 if(a.api.D.get(f,"special").onHitStatus.stacks!==3||a.api.D.get(f,"special").cooldown!==2||b.api.D.get(f,"special").onHitStatus.stacks!==2||b.api.D.get(f,"special").cooldown!==1)throw Error("refinement definitions");
 checks.push("refined L6 three stacks/CD2 versus two stacks/CD1");
 return {checks,seedCount:count,seeds,tiers:TIERS,battles:sum(cells,c=>c.n),cells};
}
if(typeof module!=="undefined")module.exports={setup,kit,run,experiment,refine,contracts,VARIANTS,REFINEMENTS,TIERS,SQUADS};
if(typeof require!=="undefined"&&typeof module!=="undefined"&&require.main===module){
 const fs=require("node:fs"),lab=require("../../combat-lab-real/engine.js");
 const source=lab.files.map(f=>fs.readFileSync(f,"utf8")).join("\n"),labSource=fs.readFileSync("combat-lab-real/engine.js","utf8");
 console.log(JSON.stringify((process.argv[3]==="refine"?refine:experiment)(source,labSource,Number(process.argv[2]||20)),null,2));
}
/* B15.2B isolated real-core defense candidate. No production import. */
"use strict";
const CONFIGS={
 ref:{},art:{art:true,react:true},guard:{art:true,react:false},
 liora:{liora:true},both:{art:true,react:true,liora:true},
 "both-noreact":{art:true,react:false,liora:true},
 "both-leader5":{art:true,react:true,liora:true,leader:5},
 "both-leader10":{art:true,react:true,liora:true,leader:10},
 "ref-leader10":{leader:10},
 "both-flex":{art:true,react:true,liora:true,artCap:true},
 "both-recover":{art:true,react:true,liora:true,recover:true},
 "both-earlypassive":{art:true,react:true,liora:true,earlyPassive:true}
};
const TIERS={early:{skill:1,level:2,rush:.9,hold:1.05,area:.95},trained:{skill:6,level:12,rush:1.12,hold:1.30,area:1.15}};
const SQUADS=[["ren","art"],["ren","art","nada"],["ren","liora","nada"],["art","nada","sava"],["liora","nada","sava"],["ren","art","liora"],["b14-striker","liora","b14-medic","sava"],["ren","art","nada","liora","sava"]];
function rep(s,a,b,n=1){if(s.split(a).length!==n+1)throw Error("B15.2B anchor "+a);return s.split(a).join(b);}
function kit(actor,id,base,c){
 if(!base||actor.side!=="ally")return base;
 const i=(actor.skillLevels?.[id]??1)-1,curve=a=>a[i];
 if(i<0||i>5)throw Error("skill");
 if(actor.id==="liora"&&id==="leader"&&c.leader!==undefined)return {...base,modifiers:base.modifiers.map(m=>({...m,value:c.leader}))};
 if(actor.id==="art"&&c.art){
  if(id==="passive")return {...base,combatRules:{b15React:!!c.react,fraction:curve([.4,.42,.44,.46,.48,.5]),cap:curve([.6,.65,.7,.75,.8,.9])}};
  if(id==="basic")return {...base,multiplier:curve([1,1.04,1.08,1.12,1.18,1.24])};
  if(id==="special")return {...base,insurancePercent:curve([40,42,44,46,48,50]),insuranceTurns:2,cooldown:2,b15Guard:{kind:"art",hits:1,turns:2,fraction:curve(c.artCap?[.5,.52,.54,.56,.58,.6]:[.4,.42,.44,.46,.48,.5]),cap:curve(c.artCap?[1.1,1.15,1.2,1.25,1.3,1.4]:[.8,.85,.9,.95,1,1.1]),recover:c.recover?.35:0}};
  if(id==="powerful"){const a={...base,multiplier:curve([1.05,1.09,1.13,1.17,1.21,1.25]),cooldown:3,weakening:0,b15Disrupt:true};delete a.disruptTurns;delete a.disruptDelay;return a;}
 }
 if(actor.id==="liora"&&c.liora){
  const group={kind:"liora",hits:1,turns:2,fraction:curve([.3,.32,.34,.36,.38,.4]),cap:curve([.65,.7,.75,.8,.85,.9])};
  if(id==="passive")return {...base,combatRules:{b15Threshold:curve(c.earlyPassive?[45,45,48,48,50,50]:[35,35,38,38,40,40]),b15Guard:group}};
  if(id==="basic")return {...base,multiplier:curve([.9,.95,1,1.04,1.08,1.15])};
  if(id==="special")return {...base,guardHits:2,tauntTurns:2,cooldown:3,b15Guard:{kind:"liora",hits:2,turns:2,fraction:curve([.35,.38,.4,.42,.45,.48]),cap:.9}};
  if(id==="powerful")return {...base,guardHits:1,cooldown:3,b15Guard:group};
 }
 return base;
}
// Injected into CombatCore closure. All state lives on the battle or fighters.
function primitives(){
 function b15count(b,k,n=1){const s=b.b15Stats??={};s[k]=(s[k]??0)+n;}
 function b15prune(b){for(const f of b.fighters){if(!f.b15Guards)continue;f.b15Guards=f.b15Guards.filter(g=>f.hp>0&&g.hits>0&&g.turns>0&&b.fighters.some(o=>o.id===g.owner&&o.hp>0));}}
 function b15grant(b,owner,target,g){
  if(!target||target.hp<=0||owner.hp<=0)return false;
  b15prune(b);
  if(g.kind==="art")for(const f of b.fighters)if(f.b15Guards)f.b15Guards=f.b15Guards.filter(x=>x.kind!=="art"||x.owner!==owner.id);
  const fresh={...g,owner:owner.id,capDamage:Math.round(owner.physicalAttack*g.cap),turns:g.turns+(owner===target?1:0)};
  const old=(target.b15Guards??=[]).find(x=>x.kind===g.kind&&x.owner===owner.id);
  // Same-owner group guard cannot overwrite a stronger self stance.
  if(old&&old.hits>=fresh.hits&&old.fraction>=fresh.fraction&&old.capDamage>=fresh.capDamage&&old.turns>=fresh.turns)return false;
  if(old&&old.hits>fresh.hits&&old.fraction>=fresh.fraction&&old.capDamage>=fresh.capDamage)return false;
  target.b15Guards=target.b15Guards.filter(x=>x!==old);target.b15Guards.push(fresh);
  b15count(b,g.kind+"Granted",g.hits);
  if(g.recover>0){const restored=Math.max(0,Math.min(target.maxProtection-target.protection,Math.round(owner.physicalAttack*g.recover)));target.protection+=restored;b15count(b,"artRestored",restored);}
  return true;
 }
 function b15guard(b,target,damage,direct){
  b15prune(b);
  const gs=(target.b15Guards??[]).filter(g=>g.kind!=="art"||direct);
  if(!gs.length){if(target.guardHits>0){target.guardHits--;const after=Math.round(damage*.5);b15count(b,"nativeGuardBlocked",damage-after);return after;}return damage;}
  if(damage<=0)return damage;
  const options=gs.map(g=>({g,blocked:Math.min(damage,Math.round(damage*g.fraction),g.capDamage)}));
  if(target.guardHits>0)options.push({g:null,blocked:damage-Math.round(damage*.5)});
  options.sort((a,z)=>z.blocked-a.blocked||String(a.g?.owner??"native").localeCompare(String(z.g?.owner??"native")));
  const best=options[0];if(!best||best.blocked<=0)return damage;
  if(best.g){if(target.side==="ally"&&damage>=target.hp+target.protection&&damage-best.blocked<target.hp+target.protection)b15count(b,best.g.kind+"LocalLethalGuard");best.g.hits--;b15count(b,best.g.kind+"GuardBlocked",best.blocked);b15count(b,best.g.kind+"GuardUsed");if(best.g.kind==="art"&&b.b15Root)b.b15Root.artGuard=true;}
  else{target.guardHits--;b15count(b,"nativeGuardBlocked",best.blocked);}
  b15prune(b);return damage-best.blocked;
 }
 function b15react(b,attacker,target,hpLoss,direct){
  const root=b.b15Root;
  if(!B15DEF.react||!direct||!b.b14Resolving||root?.id!=="powerful"||root.actor!==attacker.id||root.artGuard||root.reacted||hpLoss<=0||attacker.side!=="enemy"||target.side!=="ally")return hpLoss;
  const art=b.fighters.find(f=>f.id==="art"&&f.hp>0&&f.id!==target.id&&f.protection>0&&!f.b15ReactUsed);
  if(!art)return hpLoss;
  const rules=passiveCombatRules(art),n=Math.min(hpLoss,Math.round(hpLoss*rules.fraction),Math.round(art.physicalAttack*rules.cap),art.protection);
  if(n<=0)return hpLoss;
  if(hpLoss>=target.hp&&hpLoss-n<target.hp)b15count(b,"artLocalLethalReact");art.protection-=n;art.b15ReactUsed=true;root.reacted=true;b15count(b,"artReactBlocked",n);b15count(b,"artReactUsed");return hpLoss-n;
 }
 function b15finish(b,actor){
  const root=b.b15Root;
  if(B15DEF.liora&&root?.cross?.length){
   const l=b.fighters.find(f=>f.id==="liora"&&f.hp>0&&!(f.emergencyGuardCooldown>0));
   if(l){
    const rules=passiveCombatRules(l),eligible=root.cross.map(id=>b.fighters.find(f=>f.id===id)).filter(f=>f&&f.hp>0&&f.id!==l.id);
    eligible.sort((a,z)=>a.hp/a.maxHp-z.hp/z.maxHp||a.id.localeCompare(z.id));
    if(eligible.length&&b15grant(b,l,eligible[0],rules.b15Guard)){l.emergencyGuardCooldown=3;b15count(b,"lioraPassiveUsed");}
   }
  }
  if(actor.id==="art"&&B15DEF.art)actor.b15ReactUsed=false;
  if(actor.b15Guards)for(const g of actor.b15Guards)g.turns--;
  b15prune(b);delete b.b15Root;
 }
 function b15cross(b,target,old){
  if(!B15DEF.liora||!b?.b15Root||target.side!=="ally"||target.hp<=0||old<=target.hp)return;
  const l=b.fighters.find(f=>f.id==="liora"&&f.hp>0&&f.id!==target.id);
  const threshold=l&&passiveCombatRules(l)?.b15Threshold;
  if(threshold&&old*100>threshold*target.maxHp&&target.hp*100<=threshold*target.maxHp)b.b15Root.cross.push(target.id);
 }
 function b15disrupt(b,actor,target){
  if(target.hp<=0)return;
  if(target.b14Prepared){
   if(b.statusChecks===true&&!BattleRng.roll(b,statusChance(actor,target)).hit){b15count(b,"artDisruptResisted");return;}
   CombatStatusCore.apply(target,"disrupted-plan",0,2);target.tacticalDisruptDelay=0;b15count(b,"artDisruptApplied");
  }else{applyNegativeStatus(b,actor,target,Math.max(1,target.weakenAttacks),"physical",false);b15count(b,"artFallbackAttempt");}
 }
}
function setup(source,labSource,variant,tier,options={}){
 const c=CONFIGS[variant],t=TIERS[tier];if(!c||!t)throw Error("config");
 let s=source,l=labSource;
 l=rep(l,"skillLevels:{basic:1,special:1,powerful:1,passive:1}","skillLevels:"+JSON.stringify({basic:t.skill,special:t.skill,powerful:t.skill,passive:t.skill}));
 l=rep(l,"{level:2,stars:1}","{level:"+t.level+",stars:1}");
 l=rep(l,'const scale=scenario==="rush"?.90:.72;', 'const scale=('+JSON.stringify({rush:t.rush,hold:t.hold,area:t.area,mixed:.72,priority:.72})+')[scenario];');
